#manufacturing input{box-sizing:border-box}#manufacturing details{margin-top:12px}#manufacturing summary{cursor:pointer;min-height:36px}.mfg-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.mfg-kpis strong{font-size:26px}.mfg-kpis small{display:block;color:var(--muted)}
