nav.side a{display:block;padding:.55rem .6rem;border-radius:8px;text-decoration:none;color:var(--ink);min-height:44px;line-height:1.9}
nav.side a[aria-current=page]{background:var(--pri);color:var(--pri-ink);font-weight:600}
nav.side .grp{font-size:.72rem;text-transform:uppercase;letter-spacing:.06em;color:var(--mut);margin:.6rem .6rem .1rem}
main{padding:12px 16px 40px;min-width:0}
.grid{display:grid;gap:12px;grid-template-columns:1fr}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:12px;min-width:0}
.kpi{font-size:1.6rem;font-weight:700}.kpi small{display:block;font-size:.78rem;font-weight:400;color:var(--mut)}
.btn,button{font:inherit;min-height:40px;padding:.4rem .8rem;border-radius:8px;border:1px solid var(--line);background:var(--card);color:var(--ink);cursor:pointer}
.btn.pri,button.pri{background:var(--pri);color:var(--pri-ink);border-color:var(--pri)}
.btn.bad,button.bad{color:var(--bad);border-color:var(--bad)}
button[disabled]{opacity:.5;cursor:not-allowed}
button.help{min-height:28px;min-width:28px;padding:0 .4rem;border-radius:50%;font-size:.8rem;color:var(--pri)}
.helpbox{background:var(--synbg);border-left:4px solid var(--pri);padding:.5rem .7rem;margin:.4rem 0;border-radius:6px;font-size:.88rem}
.helpbox b{display:inline-block;min-width:3.2rem}
input,select,textarea{font:inherit;width:100%;max-width:100%;min-height:40px;padding:.35rem .5rem;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink)}
textarea{min-height:64px}label{display:block;font-size:.85rem;color:var(--mut);margin:.4rem 0 .15rem}
.row{display:flex;flex-wrap:wrap;gap:.5rem;align-items:center}.row>*{min-width:0}
.tbl-wrap{overflow-x:auto;max-width:100%}
table{border-collapse:collapse;width:100%;font-size:.88rem}th,td{text-align:left;padding:.4rem .5rem;border-bottom:1px solid var(--line);vertical-align:top}
th{color:var(--mut);font-weight:600;white-space:nowrap}
.pill{display:inline-block;padding:.05rem .5rem;border-radius:99px;font-size:.75rem;font-weight:600;background:var(--line);color:var(--ink)}
.pill.ok{background:var(--okbg);color:var(--ok)}.pill.warn{background:var(--warnbg);color:var(--warn)}.pill.bad{background:var(--badbg);color:var(--bad)}.pill.syn{background:var(--synbg);color:var(--syn)}
.nc{background:var(--warnbg);color:var(--warn);border:1px dashed var(--warn);border-radius:6px;padding:.1rem .4rem;font-weight:600;font-size:.85rem}
.msg{padding:.5rem .7rem;border-radius:8px;margin:.5rem 0}.msg.err{background:var(--badbg);color:var(--bad)}.msg.okm{background:var(--okbg);color:var(--ok)}
.bar-h{height:14px;background:var(--line);border-radius:7px;overflow:hidden}.bar-h>span{display:block;height:100%;background:var(--pri);width:0}
.funnel .fr{display:grid;grid-template-columns:7.5rem 1fr 3rem;gap:.5rem;align-items:center;margin:.3rem 0}
.board{display:grid;gap:10px;grid-template-columns:1fr}
.col{background:var(--bg);border:1px solid var(--line);border-radius:var(--r);padding:8px;min-width:0}
.col h3{margin:.1rem 0 .4rem;display:flex;justify-content:space-between}
.opp{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:8px;margin:6px 0;overflow-wrap:anywhere}
.tl{list-style:none;margin:0;padding:0 0 0 12px;border-left:2px solid var(--line)}.tl li{margin:.5rem 0;overflow-wrap:anywhere}.tl time{display:block;font-size:.75rem;color:var(--mut)}
.steps{display:flex;flex-wrap:wrap;gap:.3rem;margin:.4rem 0}.steps .pill{white-space:nowrap}
.wrap{overflow-wrap:anywhere}
.mut{color:var(--mut)}.small{font-size:.8rem}
.toast{position:fixed;left:16px;right:16px;bottom:16px;z-index:50}
@media (min-width:900px){
 .shell{display:grid;grid-template-columns:230px minmax(0,1fr)}
 nav.side{display:block;border-bottom:0;border-right:1px solid var(--line);min-height:calc(100vh - 90px);position:sticky;top:48px;align-self:start}
 #menu-btn{display:none}
 main{padding:16px 24px 48px}
 .grid.c2{grid-template-columns:repeat(2,minmax(0,1fr))}.grid.c3{grid-template-columns:repeat(3,minmax(0,1fr))}.grid.c4{grid-template-columns:repeat(4,minmax(0,1fr))}
 .board{grid-template-columns:repeat(auto-fit,minmax(190px,1fr))}
}
@media (min-width:560px) and (max-width:899px){.grid.c4,.grid.c3{grid-template-columns:repeat(2,minmax(0,1fr))}}

